<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Http\Requests\UpdateAgreementTemplateRequest;use App\Models\AgreementTemplate;use App\Services\ActivityLogger;use Illuminate\Http\RedirectResponse;use Illuminate\Support\Facades\DB;use Illuminate\View\View;
class AgreementTemplateController extends Controller {public function index():View{return view('admin.agreement-templates.index',['templates'=>AgreementTemplate::orderByDesc('is_default')->get()]);}public function edit(AgreementTemplate $template):View{return view('admin.agreement-templates.edit',compact('template'));}public function update(UpdateAgreementTemplateRequest $request,AgreementTemplate $template,ActivityLogger $logger):RedirectResponse{DB::transaction(function()use($request,$template){if($request->validated('is_default'))AgreementTemplate::whereKeyNot($template->id)->update(['is_default'=>false]);$template->update($request->validated());});$logger->log('updated','agreement-templates',$template,'Agreement template updated.');return redirect()->route('admin.agreement-templates.index')->with('success','Template updated. Existing agreement snapshots were not changed.');}}
